"""The public face of the Gnani models: things a visitor can hear, generated by the real APIs.

* `story(lang)`: one record becoming proof, start to finish. Every line is spoken by Timbre (three
  different voices), and the worker's and employer's lines are then transcribed back by Prisma, so the
  page shows what Prisma actually heard, and what Saakshi's number rules read from it.
* `hello(lang)`: Saakshi greeting a worker in each of the nine languages.

Generated once, then served from disk.
"""

from __future__ import annotations

import asyncio
import json
from datetime import date

from . import audio, gnani, langs, lines
from .config import settings
from .numbers import parse_amount

FOLDER = settings.audio_dir / "showcase"
AGENT, WORKER, EMPLOYER = "Nalini", "Urmila", "Vikrant"
_locks: dict[str, asyncio.Lock] = {}

SCRIPT = {
    "hi-IN": [
        ("worker", WORKER, "इस महीने मेहता जी के यहाँ खाना बनाया, पौने पाँच हज़ार मिले।"),
        ("saakshi", AGENT, None),                      # the real read-back, built by lines.readback
        ("worker", WORKER, "हाँ, सही है।"),
        ("saakshi", AGENT, None),                      # the real call claim, built by lines.call_claim
        ("employer", EMPLOYER, "वो क्या काम करती हैं हमारे यहाँ?"),
        ("saakshi", AGENT, "Sunita जी के हिसाब से वे आपके यहाँ खाना बनाती हैं। तो क्या यह सही है?"),
        ("employer", EMPLOYER, "हाँ, बिल्कुल सही है।"),
        ("saakshi", AGENT, None),                      # lines.THANKS_VERIFIED
    ],
    "en-IN": [
        ("worker", WORKER, "This month I cooked at Mehta ji's house and got four thousand seven hundred and fifty rupees."),
        ("saakshi", AGENT, None),
        ("worker", WORKER, "Yes, that's right."),
        ("saakshi", AGENT, None),
        ("employer", EMPLOYER, "What work does she do at our place?"),
        ("saakshi", AGENT, "According to Sunita, they do the cooking for you. So, is that right?"),
        ("employer", EMPLOYER, "Yes, that's absolutely correct."),
        ("saakshi", AGENT, None),
    ],
}


def _scripted(lang: str, i: int) -> str:
    today = date.today()
    period = {"start": today.replace(day=1).isoformat(), "end": today.isoformat(), "label": ""}
    entry = {"employer_name": "Mehta ji" if lang == "en-IN" else "मेहता जी", "period": period, "amount": 4750, "paid": "yes"}
    if i == 1:
        return lines.readback([entry], lang)
    if i == 3:
        return lines.call_claim("Sunita", [{"period": period, "amount": 4750, "days": None}], lang, "cook")
    return lines.THANKS_VERIFIED[lang].format(worker="Sunita")


def _amount_note(heard: str) -> dict:
    """What Saakshi's number rules read from Prisma's actual transcript, and from which words."""
    import re
    m = re.search(r"((?:पौने|साढ़े|सवा|ढाई|paune|saade|sava|dhai)\s*)?(?:₹\s*)?[\d,]+(?:\s*(?:हज़ार|हजार|thousand|rupees))?", heard, re.I)
    return {"parsed_amount": parse_amount(heard), "parsed_from": (m.group(0).strip() if m else heard)}


def _clip(name: str, wav: bytes) -> dict:
    FOLDER.mkdir(parents=True, exist_ok=True)
    (FOLDER / name).write_bytes(wav)
    return {"url": f"/audio/showcase/{name}", "duration": audio.duration_s(wav), "peaks": audio.peaks(wav, 48)}


async def story(lang: str = "hi-IN") -> dict:
    lang = lang if lang in SCRIPT else "hi-IN"
    cached = FOLDER / f"story_{lang}.json"
    if cached.exists():
        out = json.loads(cached.read_text())
        if out["turns"] and out["turns"][0].get("heard"):          # always the parser's current reading
            out["turns"][0].update(_amount_note(out["turns"][0]["heard"]))
        return out
    async with _locks.setdefault(f"story{lang}", asyncio.Lock()):
        if cached.exists():
            return json.loads(cached.read_text())
        turns = []
        for i, (who, voice, text) in enumerate(SCRIPT[lang]):
            text = text or _scripted(lang, i)
            sp = await gnani.timbre_speak(text, voice=voice, language=lang)
            t = {"who": who, "voice": voice, "text": text, "audio": _clip(f"story_{lang}_{i}.wav", sp.audio),
                 "timbre_ms": round(sp.latency_ms)}
            if who != "saakshi":                     # what Saakshi actually hears: Prisma on the spoken audio
                heard = await gnani.prisma_transcribe(sp.audio, language=lang)
                t["heard"] = heard.text
                t["prisma_ms"] = round(heard.latency_ms)
                if i == 0:
                    t.update(_amount_note(heard.text))
            turns.append(t)
        out = {"lang": lang, "turns": turns}
        cached.write_text(json.dumps(out, ensure_ascii=False))
        return out


HELLO = "Hello! I'm Saakshi. Tell me, in your own language, where you worked and how much you earned. I'll keep the record for you."
HELLO_HI = "नमस्ते! मैं साक्षी हूँ। अपनी भाषा में बताइए, कहाँ काम किया और कितने पैसे मिले। रिकॉर्ड मैं रखूँगी।"


async def hello(lang: str) -> dict:
    if not langs.valid(lang):
        lang = "hi-IN"
    cached = FOLDER / f"hello_{lang}.json"
    if cached.exists():
        return json.loads(cached.read_text())
    async with _locks.setdefault(f"hello{lang}", asyncio.Lock()):
        if cached.exists():
            return json.loads(cached.read_text())
        text = HELLO_HI if lang == "hi-IN" else await langs.localize(HELLO, lang)
        sp = await gnani.timbre_speak(text, voice=AGENT, language=lang)
        heard = await gnani.prisma_transcribe(sp.audio, language=lang)
        out = {"lang": lang, "text": text, "audio": _clip(f"hello_{lang}.wav", sp.audio), "heard": heard.text,
               "timbre_ms": round(sp.latency_ms), "prisma_ms": round(heard.latency_ms)}
        cached.write_text(json.dumps(out, ensure_ascii=False))
        return out


async def warm() -> None:
    """Prepare everything in the background after startup, so the first visitor doesn't wait."""
    for lang in ("hi-IN", "en-IN"):
        try:
            await story(lang)
        except Exception:                                # noqa: BLE001 - best effort; generated on demand later
            pass
    for lang in langs.LANGS:
        try:
            await hello(lang)
        except Exception:                                # noqa: BLE001
            pass
